{
  "contract": "TraderSpirits",
  "closure": {
    "site_function": "mintByUser",
    "site_call": ".call",
    "functions": [
      "mintByUser",
      "mintByOwner",
      "giftMint",
      "airDropToken"
    ],
    "justification": "All functions that modify publicMintId, publicMinted, totalMinted, or walletMinted must be included to ensure soundness, as they touch the exposed state."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "mintByUser",
      "mintByOwner",
      "giftMint",
      "airDropToken"
    ],
    "nesting_bound": {
      "mintByUser": 1
    }
  },
  "phases": {
    "function": "mintByUser",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Tokens being minted during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "publicMinted + inFlight <= publicMintLimit",
    "stable_formula": "publicMinted <= publicMintLimit",
    "kind": "bounded"
  },
  "composition": {
    "target_property": "publicMinted <= publicMintLimit",
    "rule": "The exposure invariant ensures that the number of minted tokens does not exceed the limit during reentrant calls."
  }
}
